const wa = $('WAHA Trigger').first().json;
const artist = $input.first().json;
const phoneRaw = wa.event?.payload?.from || wa.event?.payload?.author || '';

return [{
  json: {
    phone: phoneRaw.replace(/@c\.us$/, ''),
    chatId: wa.event?.payload?.from || phoneRaw,
    messageText: wa.event?.payload?.body?.text || '',
    artist_id: artist.id,
    artist_name: artist.nome,
    wa_session_slug: artist.wa_session_slug || wa.event?.session,
  }
}];

const output = $input.first().json;
const lead = $('Upsert Lead').first().json;
let pipeline = lead.pipeline_status || 'novo';

if (pipeline === 'novo' && output.output && output.output.length > 0) {
  pipeline = 'qualificando';
}

return [{
  json: {
    lead_id: lead.id,
    pipeline_status: pipeline,
    artist_id: lead.artist_id,
    last_message_at: new Date().toISOString(),
  }
}];
